import{_ as s,o as a,c as d,af as e}from"./chunks/framework.D75dE8dq.js";const g=JSON.parse('{"title":"第2章 基础语法速通","description":"","frontmatter":{},"headers":[],"relativePath":"pages/markdown/02.md","filePath":"pages/markdown/02.md","lastUpdated":1782342217000}'),i={name:"pages/markdown/02.md"};function n(r,t,l,o,p,h){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="第2章-基础语法速通" tabindex="-1">第2章 基础语法速通 <a class="header-anchor" href="#第2章-基础语法速通" aria-label="Permalink to &quot;第2章 基础语法速通&quot;">​</a></h1><h2 id="_1-标题语法" tabindex="-1">1. 标题语法 <a class="header-anchor" href="#_1-标题语法" aria-label="Permalink to &quot;1. 标题语法&quot;">​</a></h2><p><strong>语法速记</strong></p><hr><p>一级标题：<code># 我是标题</code>（独占一行，<code>#</code> 后必须空格）</p><p>六级标题：<code>###### 最小标题</code></p><p>百度 SEO：页面只能有 1 个 H1；H2-H6 用于章节，利于生成富摘要（FAQ/目录）</p><p><strong>常见坑</strong></p><hr><table tabindex="0"><thead><tr><th>错误写法</th><th>结果</th><th>修复</th></tr></thead><tbody><tr><td><code>#我是标题</code></td><td>普通文本</td><td><code># 我是标题（空格）</code></td></tr><tr><td><code>####### 七级</code></td><td>仍是 H6</td><td>Markdown 只到六级</td></tr><tr><td>一行内多个 <code># 标题1</code> <code># 标题2</code></td><td>解析失败</td><td>每行一个标题</td></tr></tbody></table><p><strong>即时预览</strong></p><hr><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 大标题（H1）</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 二级（H2）</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 三级（H3）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>→ 右侧实时渲染树形目录，百度爬虫秒懂结构</p><h2 id="_2-段落与换行" tabindex="-1">2. 段落与换行 <a class="header-anchor" href="#_2-段落与换行" aria-label="Permalink to &quot;2. 段落与换行&quot;">​</a></h2><p><strong>段落规则</strong></p><hr><p>• 空一行 = 新段落</p><p>• 行尾加两个空格 ␣␣再回车 = 同段内换行（软换行）</p><p>• 直接回车无效果，浏览器会合并成一段</p><pre><code>为方便展示空格效果，在本课程中使用 ␣ 代指空格，实际使用中请直接使用空格 。\n</code></pre><p><strong>3 个高频坑</strong></p><hr><table tabindex="0"><thead><tr><th>写法</th><th>结果</th><th>正确姿势</th></tr></thead><tbody><tr><td>回车一次</td><td>连成一段</td><td>空一行 或 行尾␣␣</td></tr><tr><td>行尾␣</td><td>无换行</td><td>必须是两个空格</td></tr><tr><td>用 <code>&lt;br &gt;</code></td><td>能换行，但失去纯文本优雅</td><td>建议行尾␣␣</td></tr></tbody></table><p><strong>即时演示</strong></p><hr><p>源码：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">第一段末尾␣␣</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">仍在</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">第一段</span></span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">空一行才是第二段</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>渲染效果</strong>：</p><p>第一段末尾<br> 仍在 第一段</p><p>空一行才是第二段</p><h2 id="_3-强调语法" tabindex="-1">3. 强调语法 <a class="header-anchor" href="#_3-强调语法" aria-label="Permalink to &quot;3. 强调语法&quot;">​</a></h2><p><strong>语法速记</strong></p><hr><p>斜体：<code>*内容*</code> 或 <code>_内容_</code><br> 粗体：<code>**内容**</code> 或 <code>__内容__</code><br> 组合：<code>***内容***</code> → 斜粗体（兼容 99% 渲染器）</p><p><strong>SEO 小贴士</strong></p><hr><table tabindex="0"><thead><tr><th>强调方式</th><th>搜索引擎权重</th><th>建议场景</th></tr></thead><tbody><tr><td>斜体</td><td>几乎不加分，仅视觉提示</td><td>引用、书名</td></tr><tr><td>粗体</td><td>小幅提升关键词相关度</td><td>核心术语、步骤</td></tr><tr><td>滥用强调</td><td>降权风险</td><td>每段 ≤3 处</td></tr></tbody></table><p>即时 Demo</p><hr><p>源码：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">让 </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*搜索引擎*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 发现 </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**关键词**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 的*</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**权重**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>渲染： 让 <em>搜索引擎</em> 发现 <strong>关键词</strong> 的<em><strong>权重</strong></em>。</p><h2 id="_4-列表" tabindex="-1">4. 列表 <a class="header-anchor" href="#_4-列表" aria-label="Permalink to &quot;4. 列表&quot;">​</a></h2><p><strong>语法速查</strong></p><hr><p>无序：<code>- 苹果</code> <code>* 香蕉</code> <code>+ 橙子</code>（符号后必须空格）<br> 有序：<code>1. 第一步</code> <code>2. 第二步</code>（数字不必连续，渲染自动纠正）<br> 任务：<code>- [ ] 未做</code> <code>- [x] 已完成</code>（中括号内空格或 x）</p><p><strong>语义化 &amp; SEO</strong></p><hr><table tabindex="0"><thead><tr><th>类型</th><th>语义</th><th>搜索引擎理解</th><th>示例场景</th></tr></thead><tbody><tr><td>无序</td><td>同级并列项</td><td><code>&lt;ul&gt;</code></td><td>购物清单</td></tr><tr><td>有序</td><td>步骤/排行</td><td><code>&lt;ol&gt;</code></td><td>安装教程</td></tr><tr><td>任务</td><td>交互待办</td><td><code>&lt;input type=&quot;checkbox&quot;&gt;</code></td><td>PRD 需求</td></tr></tbody></table><p><strong>缩进嵌套</strong></p><hr><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 一级</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 二级</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 嵌套有序</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 继续</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>渲染效果：</p><ul><li>一级 <ul><li>二级 <ol><li>嵌套有序</li><li>继续</li></ol></li></ul></li></ul><h2 id="_5-链接与图片" tabindex="-1">5. 链接与图片 <a class="header-anchor" href="#_5-链接与图片" aria-label="Permalink to &quot;5. 链接与图片&quot;">​</a></h2><p>语法速查</p><hr><ul><li>链接：<code>[显示文字](URL &quot;可选提示&quot;) </code></li><li>图片：<code>![alt](URL &quot;可选标题&quot;)</code></li><li>相对路径：<code>![流程图](./img/flow.png) </code></li><li>新窗口：<code>[外链](https://xxx.com){:target=&quot;_blank&quot;}</code>（非通用，部分渲染器需 HTML）</li></ul><p><strong>3 种路径场景</strong></p><hr><table tabindex="0"><thead><tr><th>场景</th><th>写法示例</th><th>注意</th></tr></thead><tbody><tr><td>同目录</td><td>./logo.png ./</td><td>可省</td></tr><tr><td>子目录</td><td>img/logo.png</td><td>文件夹随仓库走</td></tr><tr><td>绝对图床</td><td><a href="https://cdn.xxx.com/logo.png" target="_blank" rel="noreferrer">https://cdn.xxx.com/logo.png</a></td><td>记得 HTTPS 防浏览器拦截</td></tr></tbody></table><p><strong>图床 3 步法</strong></p><hr><p>① 免费：GitHub + jsDelivr CDN<br> ② 高速：阿里云 OSS + 自定义域名<br> ③ 防盗链：OSS → 权限管理 → Referer 白名单 <a href="https://xn--6qqv7i2xdt95b/" target="_blank" rel="noreferrer">https://你的域名/</a>*</p><p><strong>SEO &amp; 无障碍</strong></p><hr><ul><li><strong>alt 必填</strong>：百度识图 + 视障朗读</li><li><strong>宽度自适应</strong>：<code>![alt](URL){ width=80% }</code>（Typora 支持，非通用）</li><li><strong>懒加载</strong>：<code>&lt;img src=&quot;URL&quot; loading=&quot;lazy&quot;&gt;</code>（直接写 HTML，非通用）</li></ul><h2 id="_6-代码" tabindex="-1">6. 代码 <a class="header-anchor" href="#_6-代码" aria-label="Permalink to &quot;6. 代码&quot;">​</a></h2><p><strong>两种写法速记</strong></p><hr><ul><li>行内代码：<code>printf(&quot;Hello&quot;)</code> → printf(&quot;Hello&quot;)</li><li>围栏代码块：<div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ```js</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Markdown&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ```</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li></ul><p>→ 自动高亮（highlight.js 2025 内置 197 种语言）</p><p><strong>常见语言标识</strong></p><hr><table tabindex="0"><thead><tr><th>语言</th><th>围栏标记</th><th>备注</th></tr></thead><tbody><tr><td>JavaScript</td><td>```js</td><td>前端必会</td></tr><tr><td>Python</td><td>```python</td><td>AI 脚本</td></tr><tr><td>Shell</td><td>```bash</td><td>服务器指令</td></tr><tr><td>Diff</td><td>```diff</td><td>对比补丁红色高亮</td></tr></tbody></table><p><strong>SEO &amp; 阅读体验</strong></p><hr><ul><li>围栏代码块自动被<code> &lt;pre&gt;&lt;code&gt;</code> 包裹，百度富代码片段可直接收录</li><li>行内代码不要滥用：每段 ≤3 处，防止关键词密度过高</li><li>可复制按钮：highlight.js 2025 默认支持，提高停留时长</li></ul><h2 id="_7-分割线与转译" tabindex="-1">7. 分割线与转译 <a class="header-anchor" href="#_7-分割线与转译" aria-label="Permalink to &quot;7. 分割线与转译&quot;">​</a></h2><p><strong>分割线语法</strong></p><hr><ul><li>三种合法写法（独占一行，前后留空行）： <code>---</code> <code>***</code> <code>___</code></li><li>渲染效果：<code>&lt;hr&gt;</code>，可给爬虫“语义分段”信号</li><li>百度建议：每 300–400 字出现一次，降低跳出率</li></ul><p><strong>转义字符速查</strong></p><hr><table tabindex="0"><thead><tr><th>符号</th><th>写法</th><th>转义后</th></tr></thead><tbody><tr><td><code>#</code></td><td><code>\\#</code></td><td>原文#</td></tr><tr><td><code>*</code></td><td><code>\\*</code></td><td>原文*</td></tr><tr><td><code>- </code></td><td><code>\\_</code></td><td>原文_</td></tr><tr><td><code>\\ </code>本身</td><td><code>\\\\</code></td><td>原文\\</td></tr></tbody></table><p><strong>进阶用法</strong></p><hr><ul><li>SEO：分割线前后加<code>&lt;h2&gt;</code>标题，形成富摘要目录</li><li>美观：CSS 自定义 <code>hr {border:1px solid #e5e5e5;}</code></li><li>兼容性：三个以上连字符即可，无需担心数量</li></ul>',89)])])}const k=s(i,[["render",n]]);export{g as __pageData,k as default};
